#!/usr/bin/env bash
# A3: switch Envoy's balancing configuration and wait until every destination is healthy.
#
#   scripts/envoy_mode.sh a_only | round_robin | weighted | least_request
#   scripts/envoy_mode.sh                 # show the current mode and cluster health
#
# Envoy's static config is a file (envoy/<mode>.yaml, generated by envoy/render.py), so a
# change means re-creating the container with ENVOY_MODE set; that takes ~2 s and drops the
# in-flight connections, which is why the experiments switch modes between runs, never during.
set -euo pipefail
cd "$(dirname "$0")/.."
ADMIN="${ENVOY_ADMIN:-http://localhost:9901}"

current_mode() { docker inspect canteen-envoy --format '{{join .Args " "}}' 2>/dev/null | sed -n 's|.*/etc/envoy/\([a-z_]*\)\.yaml.*|\1|p'; }

show() {
  echo "mode: $(current_mode || echo '(envoy not running)')"
  curl -sf "$ADMIN/clusters" | awk -F'::' '/::health_flags::/ {printf "  %-14s %-18s %s\n", $1, $2, $4} /::weight::/ {w[$1"|"$2]=$4}' || true
}

if [ $# -eq 0 ]; then show; exit 0; fi
MODE="$1"
[ -f "envoy/$MODE.yaml" ] || { echo "unknown mode '$MODE'; expected one of: $(ls envoy/*.yaml | xargs -n1 basename | sed 's/.yaml//' | tr '\n' ' ')" >&2; exit 1; }

echo "==> envoy -> $MODE"
ENVOY_MODE="$MODE" docker compose up -d --force-recreate --no-deps envoy >/dev/null 2>&1
# wait for the admin port, then for every endpoint of both clusters to pass its health checks
for _ in $(seq 1 40); do curl -sf "$ADMIN/ready" >/dev/null 2>&1 && break; sleep 0.5; done
for _ in $(seq 1 40); do
  if ! curl -sf "$ADMIN/clusters" | grep '::health_flags::' | grep -qv '::healthy$'; then break; fi
  sleep 0.5
done
show
